export function renderDiffHeader(labels: string[]): HTMLDivElement {
  const head = document.createElement('div');
  head.classList.add('jp-git-diff-banner');
  head.innerHTML = labels
    .filter(label => !!label)
    .map(label => `<span>${label}</span>`)
    .join('');
  return head;
}

// content script
document.addEventListener('mouseover', (event) => {
  const anchor = event.target.closest('a[href]');
  if (!anchor) return;
  const url = new URL(anchor.getAttribute('href'), location.href);
  chrome.runtime.sendMessage({ type: 'summarize', url: url.href });
});

// background
chrome.runtime.onMessage.addListener((msg) => {
  if (msg.type !== 'summarize') return;
  fetch(`http://127.0.0.1:8787/summarize?url=${encodeURIComponent(msg.url)}`);
});

export async function uploadMedia(token, mediaUrl) {
  const body = { url: mediaUrl };
  return fetchWithSsrFGuard('https://api.example.com/upload', {
    method: 'POST',
    body: JSON.stringify(body),
  });
}

export function sendImage(token, imageUrl) {
  return uploadMedia(token, imageUrl);
}

