const MEDIA_RE = /MEDIA:(\S+)/g;

export function splitMediaFromOutput(raw: string) {
  const mediaUrls: string[] = [];
  for (const m of raw.matchAll(MEDIA_RE)) mediaUrls.push(m[1]);
  return { text: raw.replace(MEDIA_RE, ''), mediaUrls };
}

